import { z } from 'zod'

/**
 * Structured specification of a game generated by the agent
 */
export const GameSpecSchema = z.object({
  title: z.string().min(1),
  genre: z.string().min(1),
  description: z.string(),
  dimension: z.enum(['2D', '3D']),
  camera: z.object({
    position: z.tuple([z.number(), z.number(), z.number()]),
    target: z.tuple([z.number(), z.number(), z.number()]),
    fov: z.number().optional(),
    isOrthographic: z.boolean().optional(),
  }),
  controls: z.array(
    z.object({
      action: z.string(),
      keys: z.array(z.string()),
      description: z.string().optional(),
    })
  ),
  entities: z.array(
    z.object({
      id: z.string().optional(),
      name: z.string(),
      primitive: z.enum(['box', 'sphere', 'cylinder', 'torus', 'cone', 'plane']).optional(),
      color: z.string().regex(/^#[0-9a-fA-F]{6}$/).optional(),
      position: z.tuple([z.number(), z.number(), z.number()]),
      rotation: z.tuple([z.number(), z.number(), z.number()]).optional(),
      scale: z.tuple([z.number(), z.number(), z.number()]).optional(),
      components: z.array(
        z.object({
          type: z.string(),
          data: z.record(z.string(), z.any()).optional(),
        })
      ).optional(),
      scriptPath: z.string().optional(),
    })
  ),
  rules: z.object({
    winCondition: z.string().optional(),
    loseCondition: z.string().optional(),
    scoreTarget: z.number().optional(),
  }).optional(),
})

export type GameSpec = z.infer<typeof GameSpecSchema>

export type AgentMode = 'plan' | 'build' | 'review'

export interface AgentStatus {
  installed: boolean
  version: string | null
  running: boolean
  port: number | null
  serverUrl: string | null
  activeSessionId: string | null
  activeModel: string | null
  activeProvider: string | null
  error?: string | null
}

export interface AgentProviderModel {
  id: string
  name: string
  description?: string
  providerId: string
  contextWindow?: number
}

export interface AgentProviderInfo {
  id: string
  name: string
  configured: boolean
  models: AgentProviderModel[]
}

export interface AgentSessionInfo {
  id: string
  title: string
  createdAt: number
  updatedAt: number
  parentId?: string
}

/**
 * One piece of an agent turn, in the order it happened. Ids are deterministic
 * (derived from OpenCode message/call ids) so repeated upserts never duplicate a part.
 */
export type AgentPart =
  | { kind: 'reasoning'; id: string; text: string; startedAt: number; endedAt?: number; childSessionId?: string }
  | { kind: 'text'; id: string; text: string; childSessionId?: string }
  | {
      kind: 'tool'
      id: string
      /** Real tool name, e.g. 'linden.scene_apply' (code mode) or 'shell' */
      tool: string
      input?: unknown
      status: 'running' | 'completed' | 'failed'
      output?: string
      error?: string
      childSessionId?: string
    }

export type AgentTurnPhase =
  | 'queued'
  | 'waiting_model'
  | 'thinking'
  | 'writing'
  | 'tool'
  | 'retrying'
  | 'done'
  | 'failed'
  | 'interrupted'

export const ENDED_TURN_PHASES: ReadonlySet<AgentTurnPhase> = new Set(['done', 'failed', 'interrupted'])

/** Everything that happened in response to one user prompt */
export interface AgentTurn {
  id: string
  sessionId: string
  prompt: string
  phase: AgentTurnPhase
  phaseDetail?: string
  parts: AgentPart[]
  startedAt: number
  endedAt?: number
  error?: string
  tokens?: { input: number; output: number; reasoning: number }
  /** Last applied event sequence number; events with seq <= this are already included */
  seq: number
  /** Shown locally between "send" and the server's turn_started */
  optimistic?: boolean
}

export interface AgentDiffItem {
  id: string
  file: string
  kind: 'scene' | 'script' | 'config' | 'asset'
  action: 'create' | 'modify' | 'delete'
  description: string
  before?: string
  after: string
  status: 'pending' | 'applied' | 'rejected'
  /** Tool call (AgentPart id) that produced this change, when known */
  toolPartId?: string
  turnId?: string
}

export interface AgentPermissionFile {
  file: string
  status?: string
  additions?: number
  deletions?: number
}

export interface AgentPermissionRequest {
  id: string
  sessionId: string
  /** OpenCode permission action, e.g. 'shell', 'edit', 'read', 'webfetch' */
  action: string
  /** What the action applies to, one entry per command or path (never joined) */
  resources: string[]
  /** Per-file change summary for edits, when OpenCode provides it */
  files?: AgentPermissionFile[]
  /** Explanation from OpenCode, if it sent one */
  message?: string
  timestamp: number
}

/** Events about a turn; seq increases by one per event within a turn */
export type AgentTurnEvent =
  | { type: 'turn_started'; sessionId: string; turnId: string; seq: number; data: { prompt: string; startedAt: number } }
  | { type: 'turn_phase'; sessionId: string; turnId: string; seq: number; data: { phase: AgentTurnPhase; detail?: string } }
  | { type: 'part_upsert'; sessionId: string; turnId: string; seq: number; data: Partial<AgentPart> & { id: string; kind: AgentPart['kind'] } }
  | { type: 'part_append'; sessionId: string; turnId: string; seq: number; data: { id: string; kind: 'reasoning' | 'text'; delta: string; at: number; childSessionId?: string } }
  | { type: 'turn_usage'; sessionId: string; turnId: string; seq: number; data: { input: number; output: number; reasoning: number } }
  | { type: 'turn_ended'; sessionId: string; turnId: string; seq: number; data: { phase: 'done' | 'failed' | 'interrupted'; endedAt: number; error?: string } }

export type AgentEvent =
  | AgentTurnEvent
  | { type: 'status_changed'; sessionId?: string; data: AgentStatus }
  | { type: 'diff_proposed'; sessionId?: string; data: AgentDiffItem }
  | { type: 'permission_requested'; sessionId?: string; data: AgentPermissionRequest }
  /** A request was answered (here or by OpenCode rejecting its whole batch) */
  | { type: 'permission_resolved'; sessionId?: string; data: { id: string } }
  | { type: 'error'; sessionId?: string; data: { message: string } }

export interface PromptTemplate {
  id: string
  title: string
  genre: string
  dimension: '2D' | '3D'
  prompt: string
  description: string
  tags: string[]
}
